sys_script_fix.script:
var SCOPE = 'x_2206627_er_tri_0';
var E = SCOPE + '_encounter', V = SCOPE + '_vitals', A = SCOPE + '_triage_assessment';

function val(table, id, field) {
  var gr = new GlideRecord(table);
  return gr.get(id) ? gr.getValue(field) : null;
}

// Find the latest test encounter
var enc = new GlideRecord(E);
enc.addQuery('patient.patient_last_name', 'StubTest');
enc.orderByDesc('sys_created_on');
enc.setLimit(1);
enc.query();

if (!enc.next()) {
  gs.error('No test encounter found. Run ER Triage - Test High Acuity Alert first.');
} else {
  var encId = enc.getUniqueValue();
  var svc = new ERTriageService();
  svc.useCache = true; // turns the cache on for this test only; the property is unchanged

  // ---------- TEST 2: CACHE ----------
  var firstId = enc.getValue('current_assessment');
  if (val(A, firstId, 'nurse_decision') == 'pending') {
    svc.recordDecision(firstId, 'accepted'); // so _findReusable skips it
  }
  var secondId = svc.runTriage(encId);
  gs.info('CACHE TEST: first ' + val(A, firstId, 'number') +
    ' | second ' + val(A, secondId, 'number') +
    ' | new record: ' + (secondId != firstId) +
    ' | same hash: ' + (val(A, firstId, 'case_hash') == val(A, secondId, 'case_hash')));

  // ---------- TEST 3: TIMER ----------
  // Backdate all vitals for this encounter by 20 minutes (ESI 2 limit is 15)
  var old = new GlideDateTime();
  old.addSeconds(-20 * 60);
  var v = new GlideRecord(V);
  v.addQuery('encounter', encId);
  v.query();
  while (v.next()) {
    v.setValue('taken_at', old);
    v.setWorkflow(false);
    v.update();
  }

  svc.flagOverdueReassessments();
  gs.info('TIMER TEST: after backdating, overdue = ' +
    val(E, encId, 'reassessment_overdue') + ' (expected 1)');

  // New vitals, then triage, should clear the flag
  var nv = new GlideRecord(V);
  nv.initialize();
  nv.setValue('encounter', encId);
  nv.setValue('taken_at', new GlideDateTime());
  nv.setValue('heart_rate', 118);
  nv.setWorkflow(false); // skip the re-triage rule; we call runTriage directly
  nv.insert();

  svc.runTriage(encId);
  gs.info('TIMER TEST: after new vitals, overdue = ' +
    val(E, encId, 'reassessment_overdue') + ' (expected 0)');
}
